parameters.functionScript:
/*
 * DOES THIS ROW WRITE? (TASK-L177). Only when it carries the concept its lesson
 * is for — the lesson page puts it on every row. Palette's specimen rows carry
 * none, so they call nothing and the kit shows a save at once, as it always did.
 */
Outputs.waits = String(Inputs.conceptId || '') !== '';

/*
 * THE LEARNER PRESSED SAVE (TASK-L177). Runs on the kit's `Saved` only — its
 * inputs do not re-run it. With no concept on the row there is no backend to
 * ask and nothing happens here. Otherwise the kit is told `saving:<token>`
 * before the call, and the answer carries the same token, new for every save:
 * that is how the kit tells THIS save's answer from the last one's, even when a
 * fast backend answers inside one frame.
 */
const conceptId = String(Inputs.conceptId || '');
if (!conceptId) return;
const token = String(Date.now()) + '-' + Math.floor(Math.random() * 1e6);
Outputs.conceptId = conceptId;
Outputs.field = String(Inputs.field || '');
Outputs.value = String(Inputs.value || '');
Outputs.token = token;
Outputs.status = 'saving:' + token;
Outputs.ask();

/*
 * THE BACKEND HAS IT (TASK-L177). Now, and only now, the kit may say ✓ Saved.
 * The fact also goes into `dbtCapturedFacts`, which the lesson page lays over
 * the facts it loaded, so moving to another step and back still shows it — the
 * page reads the learner's facts once, when it opens.
 */
const field = String(Inputs.field || '');
if (field) {
  const now = Object.assign({}, Noodl.Variables.dbtCapturedFacts || {});
  now[field] = String(Inputs.value || '');
  Noodl.Variables.dbtCapturedFacts = now;
}
Outputs.status = 'saved:' + String(Inputs.token || '');

/*
 * THE BACKEND REFUSED OR COULD NOT BE REACHED (TASK-L177). The kit gives the box
 * back with the words still in it and says it could not save. Never a ✓.
 */
Outputs.status = 'failed:' + String(Inputs.token || '');
